import * as React from "react";

import { cn } from "../lib/utils";
import { Tooltip, TooltipProvider } from "./tooltip";
import { worldMapCountries, worldMapFrame } from "./world-map-geometry";
import { equalEarth } from "./world-map-projection";

import styles from "./world-map.module.css";

export type WorldMapLocation = {
  /** Unique per location. Defaults to the label. */
  id?: string;
  /** What the tooltip and legend name the location, such as "Toronto, CA" or "Local network". */
  label: string;
  /** ISO 3166-1 alpha-2 code. Locations that share one add up to that country's tone. */
  country?: string;
  /** Without both coordinates the location has no marker and appears only in the legend. */
  lat?: number;
  lng?: number;
  count: number;
};

export type WorldMapProps = Omit<React.ComponentPropsWithoutRef<"div">, "children"> & {
  locations: WorldMapLocation[];
  /** Names the map for assistive technology, such as "Secret access locations". */
  label: string;
  /** markers sizes a square per location by count, regions tones each country by its total, both does both. */
  display?: "both" | "markers" | "regions";
  formatCount?: (count: number) => string;
  /** How many locations the legend lists before it sums the rest. */
  legendLimit?: number;
  /** Turns the legend off when the page already lists the locations. */
  legend?: boolean;
  /** Shown over the map when no location has a count. */
  empty?: React.ReactNode;
};

const steps = 4;
const markerMin = 7;
const markerMax = 20;
const defaultFormat = (count: number) =>
  `${count.toLocaleString("en-US")} ${count === 1 ? "access" : "accesses"}`;
const regionNames =
  typeof Intl !== "undefined" && "DisplayNames" in Intl
    ? new Intl.DisplayNames(["en"], { type: "region", fallback: "code" })
    : null;
const drawn = new Set(worldMapCountries.map(([code]) => code).filter(Boolean));
const regionKey = (code: string) => `region:${code}`;
const regionName = (code: string) => {
  try {
    return regionNames?.of(code) ?? code;
  } catch {
    return code;
  }
};

/** Projects a longitude and latitude into the WorldMap viewBox. */
export function projectWorldMap(lng: number, lat: number): [number, number] {
  const [x, y] = equalEarth(lng, lat);
  return [worldMapFrame.x + x * worldMapFrame.scale, worldMapFrame.y - y * worldMapFrame.scale];
}

type Target = { key: string; name: string; count: number };

function WorldMap({
  locations,
  label,
  display = "both",
  formatCount = defaultFormat,
  legendLimit = 8,
  legend = true,
  empty = "No locations",
  className,
  ...props
}: WorldMapProps) {
  const counted = React.useMemo(
    () =>
      locations
        .filter((location) => location.count > 0)
        .map((location) => ({ ...location, key: location.id ?? location.label }))
        .sort((a, b) => b.count - a.count),
    [locations]
  );
  const total = counted.reduce((sum, location) => sum + location.count, 0);

  const markers = React.useMemo(() => {
    const placed = counted.filter(
      (location) =>
        Number.isFinite(location.lat) &&
        Number.isFinite(location.lng) &&
        (display !== "regions" || !drawn.has(location.country?.toUpperCase() ?? ""))
    );
    const max = placed[0]?.count ?? 1;
    return placed.map((location) => {
      const [x, y] = projectWorldMap(location.lng!, location.lat!);
      const size = markerMin + Math.sqrt(location.count / max) * (markerMax - markerMin);
      return { ...location, name: location.label, x, y, size };
    });
  }, [counted, display]);

  const regions = React.useMemo(() => {
    const totals = new Map<string, number>();
    if (display !== "markers")
      counted.forEach((location) => {
        const code = location.country?.toUpperCase();
        if (code && drawn.has(code)) totals.set(code, (totals.get(code) ?? 0) + location.count);
      });
    const max = Math.max(1, ...totals.values());
    return { totals, step: (count: number) => Math.max(1, Math.ceil((count / max) * steps)) };
  }, [counted, display]);

  const targets: Target[] = React.useMemo(
    () =>
      display === "regions"
        ? [
            ...[...regions.totals].map(([code, count]) => ({
              key: regionKey(code),
              name: regionName(code),
              count
            })),
            ...markers
          ].sort((a, b) => b.count - a.count)
        : markers,
    [display, markers, regions]
  );
  const [focused, setFocused] = React.useState<string>();
  const active = Math.max(
    0,
    targets.findIndex((target) => target.key === focused)
  );
  const elements = React.useRef(new Map<string, SVGElement>());

  const onKeyDown = (event: React.KeyboardEvent) => {
    const last = targets.length - 1;
    const moves: Partial<Record<string, number>> = {
      ArrowRight: Math.min(active + 1, last),
      ArrowDown: Math.min(active + 1, last),
      ArrowLeft: Math.max(active - 1, 0),
      ArrowUp: Math.max(active - 1, 0),
      Home: 0,
      End: last
    };
    const next = moves[event.key];
    if (next === undefined || last < 0) return;
    event.preventDefault();
    setFocused(targets[next].key);
    elements.current.get(targets[next].key)?.focus();
  };
  const targetProps = (target: Target) => ({
    ref: (element: SVGElement | null) => {
      if (element) elements.current.set(target.key, element);
      else elements.current.delete(target.key);
    },
    role: "img",
    "aria-label": `${target.name}: ${formatCount(target.count)}`,
    tabIndex: target.key === targets[active]?.key ? 0 : -1,
    onFocus: () => setFocused(target.key)
  });
  const tip = (target: Target) => (
    <span className={styles.tip}>
      <span className={styles.tipName}>{target.name}</span>{" "}
      <span className={styles.tipCount}>{formatCount(target.count)}</span>
    </span>
  );

  const listed = counted.slice(0, legendLimit);
  const rest = counted.slice(legendLimit).reduce((sum, location) => sum + location.count, 0);
  const summary = counted.length
    ? `${counted.length} ${counted.length === 1 ? "location" : "locations"}, ${formatCount(total)}`
    : String(typeof empty === "string" ? empty : "No locations");

  return (
    <TooltipProvider>
      <div data-slot="world-map" className={cn(styles.root, className)} {...props}>
        <div className={styles.canvas} data-empty={counted.length ? undefined : ""}>
          <svg
            className={styles.svg}
            viewBox={`0 0 ${worldMapFrame.width} ${worldMapFrame.height}`}
            role="group"
            aria-label={label}
            onKeyDown={onKeyDown}
          >
            <g className={styles.land} aria-hidden={display === "regions" ? undefined : true}>
              {worldMapCountries.map(([code, d], index) => {
                const count = code ? regions.totals.get(code) : undefined;
                if (!count) return <path key={code || index} d={d} />;
                const target = { key: regionKey(code), name: regionName(code), count };
                const region = (
                  <path
                    key={code}
                    d={d}
                    className={styles.region}
                    data-step={regions.step(count)}
                    {...(display === "regions" ? targetProps(target) : {})}
                  />
                );
                return (
                  <Tooltip key={code} content={tip(target)}>
                    {region}
                  </Tooltip>
                );
              })}
            </g>
            {markers.length > 0 && (
              <g className={styles.markers}>
                {markers.map((marker) => (
                  <Tooltip key={marker.key} content={tip(marker)}>
                    <rect
                      {...targetProps(marker)}
                      className={styles.marker}
                      x={marker.x - marker.size / 2}
                      y={marker.y - marker.size / 2}
                      width={marker.size}
                      height={marker.size}
                    />
                  </Tooltip>
                ))}
              </g>
            )}
          </svg>
          {!counted.length && (
            <div className={styles.empty}>
              <span>{empty}</span>
            </div>
          )}
        </div>
        {legend && counted.length > 0 && (
          <div className={styles.legend}>
            <ul className={styles.list}>
              {listed.map((location) => {
                const placed = markers.some((marker) => marker.key === location.key);
                return (
                  <li key={location.key} className={styles.item}>
                    <span
                      className={styles.swatch}
                      data-kind={placed ? "marker" : "none"}
                      aria-hidden
                    />
                    <span className={styles.name}>{location.label}</span>
                    <span className={styles.count}>{formatCount(location.count)}</span>
                  </li>
                );
              })}
              {rest > 0 && (
                <li className={styles.item}>
                  <span className={styles.name}>{counted.length - legendLimit} more</span>
                  <span className={styles.count}>{formatCount(rest)}</span>
                </li>
              )}
            </ul>
            {display !== "markers" && regions.totals.size > 0 && (
              <div className={styles.scale} aria-hidden>
                <span>Fewer</span>
                {Array.from({ length: steps }, (_, step) => (
                  <span key={step} className={styles.step} data-step={step + 1} />
                ))}
                <span>More</span>
              </div>
            )}
          </div>
        )}
        <p className="sr-only" aria-live="polite">
          {summary}
        </p>
      </div>
    </TooltipProvider>
  );
}

export { WorldMap };

const A1 = 1.340264;
const A2 = -0.081106;
const A3 = 0.000893;
const A4 = 0.003796;
const M = Math.sqrt(3) / 2;
const radians = Math.PI / 180;

/** Equal Earth (Savric, Patterson and Jenny, 2018) in unit space, so equal areas stay equal on the map. */
export function equalEarth(lng: number, lat: number): [number, number] {
  const theta = Math.asin(M * Math.sin(lat * radians));
  const t2 = theta * theta;
  const t6 = t2 * t2 * t2;
  return [
    (lng * radians * Math.cos(theta)) / (M * (A1 + 3 * A2 * t2 + t6 * (7 * A3 + 9 * A4 * t2))),
    theta * (A1 + A2 * t2 + t6 * (A3 + A4 * t2))
  ];
}

.root {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-12);
  min-width: 0;
}
.canvas {
  position: relative;
  min-width: 0;
}
.svg {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}
.land path {
  fill: var(--cipher-map-land);
  stroke: var(--cipher-map-border);
  stroke-width: var(--cipher-size-control-border);
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}
.land .region[data-step="1"],
.step[data-step="1"] {
  --world-map-tone: 28%;
}
.land .region[data-step="2"],
.step[data-step="2"] {
  --world-map-tone: 50%;
}
.land .region[data-step="3"],
.step[data-step="3"] {
  --world-map-tone: 74%;
}
.land .region[data-step="4"],
.step[data-step="4"] {
  --world-map-tone: 100%;
}
.land .region {
  fill: color-mix(in oklab, var(--cipher-map-region) var(--world-map-tone), var(--cipher-map-land));
  transition: fill var(--cipher-duration-fast) var(--cipher-ease-standard);
}
.land .region:is(:hover, :focus-visible, [data-state$="open"]) {
  fill: color-mix(
    in oklab,
    var(--cipher-map-region) var(--world-map-tone),
    var(--cipher-map-marker) 24%
  );
}
.land .region:focus-visible {
  outline: none;
  stroke: var(--cipher-focus-ring);
  stroke-width: var(--cipher-size-focus-ring);
}
.marker {
  fill: var(--cipher-map-marker);
  stroke: var(--cipher-map-marker-line);
  stroke-width: var(--cipher-size-control-border);
  vector-effect: non-scaling-stroke;
  cursor: default;
  transition: fill var(--cipher-duration-fast) var(--cipher-ease-standard);
}
.marker:is(:hover, :focus-visible, [data-state$="open"]) {
  fill: var(--cipher-accent);
  stroke: var(--cipher-map-marker);
}
.marker:focus-visible {
  outline: none;
  stroke: var(--cipher-focus-ring);
  stroke-width: var(--cipher-size-focus-ring);
}
.canvas[data-empty] .land {
  opacity: var(--cipher-opacity-row-dim);
}
.empty {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: var(--cipher-muted);
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}
.empty > span {
  padding: var(--cipher-space-4) var(--cipher-space-8);
  background: var(--cipher-surface);
}
.tip {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.tipName {
  overflow-wrap: anywhere;
  font-weight: var(--cipher-type-label-font-weight);
}
.tipCount {
  font-variant-numeric: tabular-nums;
}
.legend {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--cipher-space-8) var(--cipher-space-24);
  min-width: 0;
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}
.list {
  display: flex;
  flex: 1 1 0;
  flex-wrap: wrap;
  gap: var(--cipher-space-4) var(--cipher-space-16);
  min-width: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}
.item {
  display: inline-flex;
  align-items: center;
  gap: var(--cipher-space-6);
  min-width: 0;
  max-width: 100%;
}
.swatch {
  flex: none;
  width: var(--cipher-space-8);
  height: var(--cipher-space-8);
  background: var(--cipher-map-marker);
}
.swatch[data-kind="none"] {
  background: transparent;
  box-shadow: inset 0 0 0 var(--cipher-size-control-border) var(--cipher-muted);
}
.name {
  min-width: 0;
  max-width: var(--cipher-size-sheet-sm);
  color: var(--cipher-muted);
  overflow-wrap: anywhere;
}
.count {
  flex: none;
  color: var(--cipher-ink);
  font-variant-numeric: tabular-nums;
}
.scale {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: var(--cipher-space-4);
  color: var(--cipher-muted);
}
.scale > span:first-child {
  margin-inline-end: var(--cipher-space-2);
}
.scale > span:last-child {
  margin-inline-start: var(--cipher-space-2);
}
.step {
  width: var(--cipher-space-10);
  height: var(--cipher-space-10);
  background: color-mix(in oklab, var(--cipher-map-region) var(--world-map-tone), var(--cipher-map-land));
}
@media (prefers-reduced-motion: reduce) {
  .land .region,
  .marker {
    transition: none;
  }
}
